// packets received will be silently discarded, and no GMRP registrations
// will be propagated from other ports. Setting this to a value of
// enabled(1) will be stored by the agent but will only take effect on the
// GMRP protocol operation if dot1dGmrpStatus also indicates the value
// enabled(1). This object affects all GMRP Applicant and Registrar state
// machines on this port. A transition from disabled(2) to enabled(1) will
// cause a reset of all GMRP state machines on this port. The value of this
// object MUST be retained across reinitializations of the management
// system.
var Dot1dPortGmrpStatus = snmp.NewColumn[EnabledStatus](snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 6, 1, 4, 1, 1, 1), snmp.KindInteger32, func(vb snmp.VarBind) (EnabledStatus, error) {
	v, err := snmp.DecodeInt32(vb)
	if err != nil {
		return EnabledStatus(0), err
	}
	return EnabledStatus(v), nil
})

// Dot1dPortGmrpFailedRegistrations is the column dot1dPortGmrpFailedRegistrations of table dot1dPortGmrpTable.
// The total number of failed GMRP registrations, for any reason, in all
// VLANs, on this port.
var Dot1dPortGmrpFailedRegistrations = snmp.NewColumn[uint32](snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 6, 1, 4, 1, 1, 2), snmp.KindCounter32, func(vb snmp.VarBind) (uint32, error) {
	return snmp.DecodeUint32(vb)
})

// Dot1dPortGmrpLastPduOrigin is the column dot1dPortGmrpLastPduOrigin of table dot1dPortGmrpTable.
// The Source MAC Address of the last GMRP message received on this port.
var Dot1dPortGmrpLastPduOrigin = snmp.NewColumn[net.HardwareAddr](snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 6, 1, 4, 1, 1, 3), snmp.KindOctetString, func(vb snmp.VarBind) (net.HardwareAddr, error) {
	return snmp.DecodeMacAddress(vb)
})

// Dot1dPortRestrictedGroupRegistration is the column dot1dPortRestrictedGroupRegistration of table dot1dPortGmrpTable.
// The state of Restricted Group Registration on this port. If the value of
// this control is true(1), then creation of a new dynamic entry is
// permitted only if there is a Static Filtering Entry for the VLAN
// concerned, in which the Registrar Administrative Control value is Normal
// Registration. The value of this object MUST be retained across
// reinitializations of the management system.
var Dot1dPortRestrictedGroupRegistration = snmp.NewColumn[bool](snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 6, 1, 4, 1, 1, 4), snmp.KindInteger32, func(vb snmp.VarBind) (bool, error) {
	return snmp.DecodeTruthValue(vb)
})

// Dot1dPortGmrpTableRow is one row of dot1dPortGmrpTable. Index carries the OID
// suffix beyond the table-entry prefix; the remaining fields are
// populated only for columns the caller passed to Walk(). Use
// Dot1dPortGmrpTableRow.Observed to tell a reported zero from a column the
// agent never answered.
type Dot1dPortGmrpTableRow struct {
	Index                                snmp.OID
	Dot1dPortGmrpStatus                  EnabledStatus
	Dot1dPortGmrpFailedRegistrations     uint32
	Dot1dPortGmrpLastPduOrigin           net.HardwareAddr
	Dot1dPortRestrictedGroupRegistration bool

	// observed carries one bit per column of this table, in
	// column-OID order, set when the walk decoded a value for
	// that column on this row.
	observed [1]uint64
}

// Observed reports whether col returned a value for this row. A column
// the agent answered reads true even when the answer was zero or empty;
// a column that was requested but never landed, one that was not passed
// to Walk, and any column of another table all read false.
func (r Dot1dPortGmrpTableRow) Observed(col snmp.AnyColumn) bool {
	switch col.Key() {
	case Dot1dPortGmrpStatus.Key():
		return r.observed[0]&(1<<0) != 0
	case Dot1dPortGmrpFailedRegistrations.Key():
		return r.observed[0]&(1<<1) != 0
	case Dot1dPortGmrpLastPduOrigin.Key():
		return r.observed[0]&(1<<2) != 0
	case Dot1dPortRestrictedGroupRegistration.Key():
		return r.observed[0]&(1<<3) != 0
	}

	return false
}

// Dot1dPortGmrpTableWalker is a table-aware walker over dot1dPortGmrpTable.
// Construct via Dot1dPortGmrpTable.Walk(ctx, sess, cols...).
type Dot1dPortGmrpTableWalker struct {
	rw    *snmp.RawWalker
	cols  []snmp.AnyColumn
	byCol map[uint32]snmp.AnyColumn
}

// Iter yields one (Index, Row) pair per row of the table walk. The
// full BulkWalk is buffered before any row is yielded, so the
// generated walker is correct over both column-major and row-major
// agent emission. Contracts:
//
//  1. Ordering: rows yield in the index's first-appearance position
//     in the agent's BulkWalk response — which for a well-behaved
//     agent equals lexicographic OID order over the index suffix.
//     This is NOT numerical order for composite-index tables
//     (e.g. ipAddrTable indexed by IP-as-OID: 192.168.0.10 sorts
//     before 192.168.0.2). Integer-keyed tables (ifTable,
//     hrProcessorTable) get numeric order for free.
//
//  2. Row presence: every index observed under the entry prefix
//     yields a row, even when only unrequested columns landed on
//     that index. The row's requested-column fields stay at zero
//     and Observed reports every column of that row as unobserved.
//
//  3. Decode error: rows for indexes strictly before the failing
//     index in appearance order flush before Walker.Fail is set,
//     preserving partial-progress visibility for the operator.
//     The failing row and anything after it are not yielded.
//     Check Err() afterwards for the terminal cause.
//
//  4. Memory profile: O(rows × requested columns) buffered before
//     the first yield. Bounded by table size, not walk position —
//     callers that broke out early via 'for row := range Iter()'
//     still pay the full-walk buffer cost.
func (tw *Dot1dPortGmrpTableWalker) Iter() iter.Seq2[snmp.OID, Dot1dPortGmrpTableRow] {
	return func(yield func(snmp.OID, Dot1dPortGmrpTableRow) bool) {
		entryWire := snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 6, 1, 4, 1, 1).WireBytes()
		buffer := make(map[string]*Dot1dPortGmrpTableRow)
		var orderIdx []snmp.OID
		var orderKey []string

		for rv := range tw.rw.Iter() {
			if !bytes.HasPrefix(rv.OID, entryWire) {
				continue
			}
			suffix := rv.OID[len(entryWire):]
			colID, colLen, okArc := snmp.RawFirstArc(suffix)
			if !okArc || colLen >= len(suffix) {
				continue
			}
			idxWire := suffix[colLen:]
			row, exists := buffer[string(idxWire)]
			if !exists {
				idx, idxErr := snmp.DecodeIndexArcs(idxWire)
				if idxErr != nil {
					continue
				}
				key := string(idxWire)
				row = &Dot1dPortGmrpTableRow{}
				buffer[key] = row
				orderIdx = append(orderIdx, idx)
				orderKey = append(orderKey, key)
			}
			_, ok := tw.byCol[colID]
			if !ok {
				continue
			}
			var derr error
			switch colID {
			case 1:
				if v, okRaw := snmp.RawInteger32(rv); okRaw {
					row.Dot1dPortGmrpStatus = EnabledStatus(v)
					row.observed[0] |= 1 << 0
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := Dot1dPortGmrpStatus.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.Dot1dPortGmrpStatus = dv
							row.observed[0] |= 1 << 0
						}
					}
				}
			case 2:
				if v, okRaw := snmp.RawCounter32(rv); okRaw {
					row.Dot1dPortGmrpFailedRegistrations = uint32(v)
					row.observed[0] |= 1 << 1
				} else {
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := Dot1dPortGmrpFailedRegistrations.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.Dot1dPortGmrpFailedRegistrations = dv
							row.observed[0] |= 1 << 1
						}
					}
				}
			case 3:
				vb, vbErr := rv.Decode()
				if vbErr != nil {
					derr = vbErr
				} else {
					dv, dErr := Dot1dPortGmrpLastPduOrigin.Decode(vb)
					if dErr != nil {
						derr = dErr
					} else {
						row.Dot1dPortGmrpLastPduOrigin = dv
						row.observed[0] |= 1 << 2
					}
				}
			case 4:
				vb, vbErr := rv.Decode()
				if vbErr != nil {
					derr = vbErr
				} else {
					dv, dErr := Dot1dPortRestrictedGroupRegistration.Decode(vb)
					if dErr != nil {
						derr = dErr
					} else {
						row.Dot1dPortRestrictedGroupRegistration = dv
						row.observed[0] |= 1 << 3
					}
				}
			}
			if derr != nil {
				for i := 0; i < len(orderKey); i++ {
					if orderKey[i] == string(idxWire) {
						break
					}
					if !yield(orderIdx[i], *buffer[orderKey[i]]) {
						tw.rw.Fail(derr)
						return
					}
				}
				tw.rw.Fail(derr)
				return
			}
		}

		for i := 0; i < len(orderIdx); i++ {
			if !yield(orderIdx[i], *buffer[orderKey[i]]) {
				return
			}
		}
	}
}

// Err returns the underlying walker's terminal error, or nil if
// the walk completed naturally.
func (tw *Dot1dPortGmrpTableWalker) Err() error {
	return tw.rw.Err()
}

// dot1dPortGmrpTableT is the singleton type of Dot1dPortGmrpTable.
type dot1dPortGmrpTableT struct{}

// Dot1dPortGmrpTable is the descriptor for the dot1dPortGmrpTable table.
var Dot1dPortGmrpTable dot1dPortGmrpTableT

// Walk launches a BulkWalk over dot1dPortGmrpTable and returns a
// table-aware iterator. Only the columns listed in cols are
// decoded; varbinds for unlisted columns are skipped. The walk
// rides the raw fast path (BulkWalkRaw); sessions or responses
// that cannot deliver raw bytes degrade transparently to the
// generic per-varbind decode.
//
// Every column in cols must be a column of dot1dPortGmrpTable. A column
// of any other table is a caller bug, not a device quirk: no request
// is sent, the iterator yields nothing, and Err reports
// snmp.ErrForeignColumn.
func (dot1dPortGmrpTableT) Walk(ctx context.Context, sess snmp.Session, cols ...snmp.AnyColumn) *Dot1dPortGmrpTableWalker {
	entry := snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 6, 1, 4, 1, 1)
	byCol := make(map[uint32]snmp.AnyColumn, len(cols))

	for _, c := range cols {
		o := c.OID()
		if o.Len() != entry.Len()+1 || !o.HasPrefix(entry) {
			return &Dot1dPortGmrpTableWalker{rw: snmp.ForeignColumnWalk(ctx, "dot1dPortGmrpTable", c)}
		}
		byCol[o.At(o.Len()-1)] = c
	}

	w := sess.BulkWalkRaw(ctx, snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 6, 1, 4, 1))

	return &Dot1dPortGmrpTableWalker{
		byCol: byCol,
		cols:  cols,
		rw:    w,
	}
}

// pBRIDGEMIBOIDDispatch maps column wire keys ([snmp.OID.WireKey]) to their
// typed AnyColumn for fast
// lookup during table-walk decoding. Per-MIB-module — no global
// registry; cross-package callers should consult OIDDispatch().
var pBRIDGEMIBOIDDispatch = map[string]snmp.AnyColumn{
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 4, 5, 1, 1).WireKey():       Dot1dTpHCPortInFrames,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 4, 5, 1, 2).WireKey():       Dot1dTpHCPortOutFrames,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 4, 5, 1, 3).WireKey():       Dot1dTpHCPortInDiscards,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 4, 6, 1, 1).WireKey():       Dot1dTpPortInOverflowFrames,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 4, 6, 1, 2).WireKey():       Dot1dTpPortOutOverflowFrames,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 4, 6, 1, 3).WireKey():       Dot1dTpPortInOverflowDiscards,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 6, 1, 1, 4, 1, 1).WireKey(): Dot1dPortCapabilities,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 6, 1, 2, 1, 1, 1).WireKey(): Dot1dPortDefaultUserPriority,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 6, 1, 2, 1, 1, 2).WireKey(): Dot1dPortNumTrafficClasses,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 6, 1, 2, 2, 1, 2).WireKey(): Dot1dRegenUserPriority,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 6, 1, 2, 3, 1, 2).WireKey(): Dot1dTrafficClass,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 6, 1, 2, 4, 1, 1).WireKey(): Dot1dPortOutboundAccessPriority,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 6, 1, 3, 1, 1, 1).WireKey(): Dot1dPortGarpJoinTime,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 6, 1, 3, 1, 1, 2).WireKey(): Dot1dPortGarpLeaveTime,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 6, 1, 3, 1, 1, 3).WireKey(): Dot1dPortGarpLeaveAllTime,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 6, 1, 4, 1, 1, 1).WireKey(): Dot1dPortGmrpStatus,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 6, 1, 4, 1, 1, 2).WireKey(): Dot1dPortGmrpFailedRegistrations,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 6, 1, 4, 1, 1, 3).WireKey(): Dot1dPortGmrpLastPduOrigin,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 17, 6, 1, 4, 1, 1, 4).WireKey(): Dot1dPortRestrictedGroupRegistration,
}

// OIDDispatch returns a shallow copy of the package's wire-key →
// AnyColumn map. The copy isolates callers from accidental mutation
// of the package-internal map.
func OIDDispatch() map[string]snmp.AnyColumn {
	out := make(map[string]snmp.AnyColumn, len(pBRIDGEMIBOIDDispatch))
	for k, v := range pBRIDGEMIBOIDDispatch {
		out[k] = v
	}
	return out
}
